SELECT l.id FROM public.locations l JOIN public.competitions c ON c.location_id=l.id JOIN public.competition_seasons cs ON cs.competition_id=c.id WHERE cs.id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' FOR UPDATE OF l;
