-33ff-40cc-9fd8-be732f6e07ca","time":"21:00:00","court":1,"round":25,"version":4,"published":"published","has_result":false},{"id":"06e00ea1-ba99-4f15-80c8-4ca621407556","away":"ec502bdd-d24e-48cf-84fb-f27f11387fda","date":"2027-05-03","home":"997291fd-33ff-40cc-9fd8-be732f6e07ca","time":"19:00:00","court":1,"round":26,"version":4,"published":"published","has_result":false},{"id":"f2d0a8c4-5960-5186-ad1a-26b3b2c9c519","away":"997291fd-33ff-40cc-9fd8-be732f6e07ca","date":"2027-05-10","home":"2368a5c2-7a91-484a-b201-fde870c85690","time":"19:00:00","court":2,"round":27,"version":1,"published":"published","has_result":false},{"id":"ae72a7d1-d5cb-5cd3-9d14-55b187c6866a","away":"8434b3b9-091d-4d8b-ab29-f857807d1c3b","date":"2027-05-17","home":"997291fd-33ff-40cc-9fd8-be732f6e07ca","time":"21:00:00","court":2,"round":28,"version":1,"published":"published","has_result":false},{"id":"848d3614-d81c-5188-9d2b-87957d263348","away":"997291fd-33ff-40cc-9fd8-be732f6e07ca","date":"2027-05-24","home":"8c867565-d3f7-4445-b799-a2b0e15b510d","time":"19:40:00","court":1,"round":29,"version":1,"published":"published","has_result":false},{"id":"b8072979-7ae1-503a-92b9-3bdb93912ec5","away":"544ff92b-0753-4e4f-9feb-bdcdf9c74a98","date":"2027-05-31","home":"997291fd-33ff-40cc-9fd8-be732f6e07ca","time":"21:00:00","court":1,"round":30,"version":1,"published":"published","has_result":false}]'::jsonb)
 AS x(id uuid,round integer,date date,version bigint,home uuid,away uuid,time time,court integer,published text,has_result boolean);
DO $$ BEGIN
 IF (select md5(jsonb_agg(to_jsonb(f) order by id)::text) from public.fixtures f)<>'108cba318df2a00406f2fd432ee3fc06' THEN RAISE EXCEPTION 'Fixture baseline changed; review required'; END IF;
 IF (select md5(jsonb_agg(to_jsonb(r) order by id)::text) from public.result_versions r)<>'fb8afcb4c1e8fe901add297074502ab0' THEN RAISE EXCEPTION 'Results changed; review required'; END IF;
 IF NOT EXISTS(select 1 from public.teams where id='997291fd-33ff-40cc-9fd8-be732f6e07ca' and competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and name='Buckle City' and legacy_id='mon-buckle-city' and status='active' and standings_eligible and profile_version=3) THEN RAISE EXCEPTION 'Buckle City baseline changed'; END IF;
 IF EXISTS(select 1 from public.teams where id='aae18510-0f33-494b-8962-d7a5e86d0bf0' or (competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and (legacy_id='mon-imole' or lower(btrim(name))='imole'))) THEN RAISE EXCEPTION 'Imole identity already exists'; END IF;
 IF NOT EXISTS(select 1 from public.competition_seasons where id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and lifecycle='active' and publication_state='published') THEN RAISE EXCEPTION 'Active Monday edition changed'; END IF;
 IF (select count(*) from imole_targets)<>29 OR (select count(distinct id) from imole_targets)<>29 OR (select count(*) from public.fixtures where competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and (home_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca' or away_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca') and round_number>1)<>29 THEN RAISE EXCEPTION 'Future replacement count changed'; END IF;
 IF EXISTS(select 1 from imole_targets c left join public.fixtures f on f.id=c.id where f.id is null or f.competition_season_id<>'62ce7ec9-459e-4acf-bec5-c6734a3199ef' or f.round_number<>c.round or c.round<=1 or f.match_date<>c.date or f.match_date<current_date or f.home_team_id<>c.home or f.away_team_id<>c.away or f.kickoff_time<>c.time or f.court<>c.court or f.schedule_version<>c.version or f.publication_state<>'published' or f.schedule_status<>'scheduled' or f.stage<>'regular_season' or exists(select 1 from public.result_versions r where r.fixture_id=f.id)) THEN RAISE EXCEPTION 'Future fixture changed or has a result; stop'; END IF;
END $$;
CREATE TEMP TABLE imole_protected ON COMMIT DROP AS select 'fixtures'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from imole_targets c where c.id=f.id)) protected_rows) as hash
UNION ALL
select 'results'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r) protected_rows) as hash
UNION ALL
select 'teams'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t where id not in('997291fd-33ff-40cc-9fd8-be732f6e07ca','aae18510-0f33-494b-8962-d7a5e86d0bf0')) protected_rows) as hash
UNION ALL
select 'notes'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) as hash
UNION ALL
select 'preferences'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) as hash
UNION ALL
select 'adjustments'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) as hash
UNION ALL
select 'editions'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) as hash
UNION ALL
select 'seasons'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s) protected_rows) as hash
UNION ALL
select 'audit'::text as kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) as hash;
CREATE TEMP TABLE imole_before_fixtures ON COMMIT DROP AS select to_jsonb(f) as data from public.fixtures f join imole_targets c on c.id=f.id;
CREATE TEMP TABLE imole_before_team ON COMMIT DROP AS select to_jsonb(t) as data from public.teams t where id='997291fd-33ff-40cc-9fd8-be732f6e07ca';
INSERT INTO public.teams(id,competition_season_id,legacy_id,name,status,standings_eligible,kit_colour)
 VALUES('aae18510-0f33-494b-8962-d7a5e86d0bf0','62ce7ec9-459e-4acf-bec5-c6734a3199ef','mon-imole','Imole','active',true,null);
UPDATE public.fixtures f SET home_team_id=case when f.home_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca' then 'aae18510-0f33-494b-8962-d7a5e86d0bf0'::uuid else f.home_team_id end,
 away_team_id=case when f.away_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca' then 'aae18510-0f33-494b-8962-d7a5e86d0bf0'::uuid else f.away_team_id end
 FROM imole_targets c WHERE f.id=c.id;
UPDATE public.teams SET status='replaced',standings_eligible=false,profile_version=profile_version+1 WHERE id='997291fd-33ff-40cc-9fd8-be732f6e07ca';
DO $$ BEGIN
 IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from imole_targets c where c.id=f.id)) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='fixtures') THEN RAISE EXCEPTION 'Protected fixtures changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='results') THEN RAISE EXCEPTION 'Protected results changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t where id not in('997291fd-33ff-40cc-9fd8-be732f6e07ca','aae18510-0f33-494b-8962-d7a5e86d0bf0')) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='teams') THEN RAISE EXCEPTION 'Protected teams changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='notes') THEN RAISE EXCEPTION 'Protected notes changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='preferences') THEN RAISE EXCEPTION 'Protected preferences changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='adjustments') THEN RAISE EXCEPTION 'Protected adjustments changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='editions') THEN RAISE EXCEPTION 'Protected editions changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='seasons') THEN RAISE EXCEPTION 'Protected seasons changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) IS DISTINCT FROM (select hash from imole_protected where kind='audit') THEN RAISE EXCEPTION 'Protected audit changed; rollback'; END IF;
 IF (select count(*) from public.teams where competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and status='active' and standings_eligible)<>16 THEN RAISE EXCEPTION 'Expected 16 active Monday teams'; END IF;
 IF (select count(*) from public.fixtures where home_team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0' or away_team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0')<>29 THEN RAISE EXCEPTION 'Expected 29 Imole fixtures'; END IF;
 IF (select count(*) from public.fixtures where (home_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca' or away_team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca') and round_number>1)<>0 THEN RAISE EXCEPTION 'Buckle still has future fixtures'; END IF;
 IF EXISTS(select 1 from imole_targets c join public.fixtures f on f.id=c.id where f.home_team_id<>case when c.home='997291fd-33ff-40cc-9fd8-be732f6e07ca' then 'aae18510-0f33-494b-8962-d7a5e86d0bf0'::uuid else c.home end or f.away_team_id<>case when c.away='997291fd-33ff-40cc-9fd8-be732f6e07ca' then 'aae18510-0f33-494b-8962-d7a5e86d0bf0'::uuid else c.away end or f.schedule_version<>c.version+1) THEN RAISE EXCEPTION 'Unexpected replacement outcome'; END IF;
 IF EXISTS(select 1 from imole_before_fixtures b join public.fixtures f on f.id=(b.data->>'id')::uuid where (to_jsonb(f)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at')<>(b.data-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at')) THEN RAISE EXCEPTION 'Unexpected fixture metadata change'; END IF;
 IF (select to_jsonb(t)-'status'-'standings_eligible'-'profile_version'-'updated_at' from public.teams t where id='997291fd-33ff-40cc-9fd8-be732f6e07ca') IS DISTINCT FROM (select data-'status'-'standings_eligible'-'profile_version'-'updated_at' from imole_before_team) THEN RAISE EXCEPTION 'Buckle identity/history changed'; END IF;
 IF EXISTS(select 1 from public.team_kickoff_preferences where team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0') OR EXISTS(select 1 from public.team_fixture_notes where team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0') OR EXISTS(select 1 from public.standing_adjustments where team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0') THEN RAISE EXCEPTION 'Unrequested profile/adjustment added'; END IF;
 IF (select count(*) from public.admin_audit_log where transaction_id=txid_current())<>31 THEN RAISE EXCEPTION 'Expected 31 audited changes'; END IF;
END $$;
COMMIT;
SELECT id,legacy_id,name,status FROM public.teams WHERE id in('997291fd-33ff-40cc-9fd8-be732f6e07ca','aae18510-0f33-494b-8962-d7a5e86d0bf0') ORDER BY name;

